    // FAQ Section
    "faq.title": "Frequently Asked Questions",
    "faq.subtitle": "Everything you need to know about our all-in-one calorie counter & food analyzer",
    "faq.q1.question": "How accurate is What The Food Calorie Analyzer?",
    "faq.q1.answer": "Our AI food calorie analyzer provides estimates with approximately ~98% accuracy for most common foods. Results may vary based on image quality and food complexity.",
    "faq.q2.question": "Can I analyze multiple food items in one image?",
    "faq.q2.answer": "Yes! What The Food analyzer can identify and provide nutritional information for multiple food items in a single image, such as a full meal on a plate.",
    "faq.q3.question": "What types of nutritional information does WTFood provide?",
    "faq.q3.answer": "Our calorie cal provides calories, macronutrients (protein, carbs, fat, sugar, fiber), estimated serving size, and additional health insights about the foods identified.",
    "faq.q4.question": "Is What The Food free to use?",
    "faq.q4.answer": "Yes, our AI food scanner is free to use and will always remain so! If you're finding it fun and want to take your healthy habits to the next level, our premium membership is an investment in your health that can pay dividends.",
    "faq.q5.question": "How does What The Food identify food from images?",
    "faq.q5.answer": "Our food calorie calculator and nutrition label scanner uses computer vision to detect and label foods in your photo, cross-referencing thousands of known dishes and ingredients to give accurate calorie and nutrition estimates.",
    "faq.q6.question": "Can AI really estimate calories from food photos?",
    "faq.q6.answer": "Yes! AI calorie scanners like What The Food analyze the shape, color, and texture of food to estimate portion size and nutrients. Accuracy depends on image clarity and food complexity.",
    "faq.q7.question": "Is there a free AI food scanner online?",
    "faq.q7.answer": "Yes. What The Food offers a completely free AI food scanner. You can upload photos from your device to instantly get calorie and nutrition data, no signups or credit cards required.",
    "faq.q8.question": "How accurate are AI food scanners compared to manual calorie tracking?",
    "faq.q8.answer": "AI food scanners are generally accurate for common dishes and everyday meals. What The Food achieves around 98% accuracy on standard foods, though results may vary for complex recipes or poor lighting.",
    "faq.q9.question": "Can I scan my meal for calories online?",
    "faq.q9.answer": "Absolutely. You can scan your meal online at WhatTheFood.io — simply upload your photo, and its innovative food analyzer will break down each food item with calorie and macro details.",
    "faq.q10.question": "Does What The Food track my meals or save my scans?",
    "faq.q10.answer": "Yes, as a premium What The Food user, you will have access to your scan history and macro analytics so you can keep track and optimize your healthy habits with personalized health context.",
    "faq.q11.question": "What foods can the AI recognize?",
    "faq.q11.answer": "Our food detection API is trained on thousands of global dishes, from fast food to homemade meals, fruits, vegetables, and desserts. It can even identify mixed plates containing multiple foods.",
    "faq.q12.question": "Can I use What The Food to track macros automatically?",
    "faq.q12.answer": "Yes! Our AI calorie counter and estimator estimates protein, carbohydrates, fats, and total calories for each food. It's a quick way to log meals without typing or weighing food manually.",
    "faq.q13.question": "What makes What The Food different from other calorie scanner apps?",
    "faq.q13.answer": "Unlike traditional calorie counters, What The Food uses a trained food recognition LLM with 98% accuracy to estimate calories and nutrients from photos instantly. It also offers great features such as personalized meal planner, customizable widget, recipe scanner, food calorie calculator, and so much more, all with a very competitive and transparent pricing stucture.",
    "faq.q14.question": "Can AI estimate portion size and serving weight from pictures?",
    "faq.q14.answer": "Yes, calorie counter recipe apps like What The Food can estimate portion sizes by analyzing plate area and food volume. What The Food uses this data to estimate servings and calorie counter content more accurately.",
    "faq.q15.question": "Is there an AI that tells you what food is in a photo?",
    "faq.q15.answer": "Yes! What The Food can tell you exactly what food is in your photo and show you its nutritional value. Just upload an image and let the AI do the rest.",
    "faq.q16.question": "Can What The Food analyze restaurant meals or recipes?",
    "faq.q16.answer": "Yes, you can upload images of restaurant dishes or home-cooked meals. Our calorie estimator food AI will identify each item and estimate calories, macros, and portion size.",
    "faq.q17.question": "How do AI food recognition apps work?",
    "faq.q17.answer": "They rely on deep learning models trained on millions of food photos. The AI detects patterns to recognize ingredients, estimate nutrients, and return results almost instantly.",
    "faq.q18.question": "Are AI food scanners safe to use?",
    "faq.q18.answer": "Yes. What The Food processes all images securely and doesn't require personal information. It's safe, private, and free to use.",
    "faq.q19.question": "What is the best free AI food scanner in 2026?",
    "faq.q19.answer": "What The Food is among the best free AI food scanners in 2026, offering fast, accurate, and ad-free calorie and macro estimation directly in your browser, with too many great features for optimizing your healthy habits.",
    
