    // Terms Page Section
    "terms.title": "Términos y Condiciones",
    "terms.lastupdated": "Última actualización:",
    "terms.section1.title": "1. Aceptación de los Términos",
    "terms.section1.content": "Al acceder y usar WhatTheFood, acepta y se compromete a cumplir con los términos y disposiciones de este acuerdo.",
    "terms.section2.title": "2. Licencia de Uso",
    "terms.section2.content": "Se otorga permiso para usar temporalmente WhatTheFood solo para uso personal y no comercial. Esta es la concesión de una licencia, no una transferencia de título.",
    "terms.section3.title": "3. Descargo de Responsabilidad",
    "terms.section3.content": "La información nutricional proporcionada es solo para fines informativos y no debe considerarse asesoramiento médico. Siempre consulte con un profesional de la salud para orientación dietética.",
    "terms.section4.title": "4. Términos de la Cuenta",
    "terms.section4.content": "Usted es responsable de mantener la seguridad de su cuenta y contraseña. WhatTheFood no puede ni será responsable de ninguna pérdida o daño por su incumplimiento de esta obligación de seguridad.",
    "terms.section5.title": "5. Términos de Suscripción",
    "terms.section5.content": "Las suscripciones Premium se facturan mensual o anualmente. Puede cancelar su suscripción en cualquier momento, y la cancelación tendrá efecto al final de su período de facturación actual.",
    "terms.section6.title": "6. Modificaciones",
    "terms.section6.content": "WhatTheFood se reserva el derecho de modificar o reemplazar estos Términos en cualquier momento. El uso continuo del servicio después de cualquier cambio constituye la aceptación de los nuevos Términos.",
    
    // Privacy Page Section
    "privacy.title": "Política de Privacidad",
    "privacy.lastupdated": "Última actualización:",
    "privacy.section1.title": "1. Información que Recopilamos",
    "privacy.section1.content": "Recopilamos información que usted nos proporciona directamente, como cuando crea una cuenta, sube imágenes de alimentos o se comunica con nosotros. Esto incluye su dirección de correo electrónico, imágenes subidas e historial de escaneos.",
    "privacy.section2.title": "2. Cómo Usamos Su Información",
    "privacy.section2.content": "Usamos la información que recopilamos para proporcionar, mantener y mejorar nuestros servicios, incluido el análisis de imágenes de alimentos y la generación de informes nutricionales. No vendemos su información personal a terceros.",
    "privacy.section3.title": "3. Seguridad de Datos",
    "privacy.section3.content": "Implementamos medidas técnicas y organizativas apropiadas para proteger su información personal contra acceso no autorizado, alteración, divulgación o destrucción.",
    "privacy.section4.title": "4. Sus Derechos",
    "privacy.section4.content": "Tiene derecho a acceder, corregir o eliminar su información personal. Puede administrar sus datos a través de la configuración de su cuenta o contactándonos directamente.",
    "privacy.section5.title": "5. Cookies",
    "privacy.section5.content": "Usamos cookies y tecnologías similares para mejorar su experiencia, analizar el uso y ayudar en nuestros esfuerzos de marketing.",
    "privacy.section6.title": "6. Contáctenos",
    "privacy.section6.content": "Si tiene preguntas sobre esta Política de Privacidad, contáctenos en privacy@whatthefood.io",
    
