    // FAQ Section
    "faq.title": "Questions fréquemment posées",
    "faq.subtitle": "Tout ce que vous devez savoir sur notre compteur de calories et analyseur d'aliments tout-en-un",
    "faq.q1.question": "Quelle est la précision de l'Analyseur de Calories What The Food ?",
    "faq.q1.answer": "Notre analyseur de calories alimentaires IA fournit des estimations avec environ ~98% de précision pour la plupart des aliments courants. Les résultats peuvent varier selon la qualité de l'image et la complexité des aliments.",
    "faq.q2.question": "Puis-je analyser plusieurs aliments dans une image ?",
    "faq.q2.answer": "Oui ! L'analyseur What The Food peut identifier et fournir des informations nutritionnelles pour plusieurs aliments dans une seule image, comme un repas complet dans une assiette.",
    "faq.q3.question": "Quels types d'informations nutritionnelles WTFood fournit-il ?",
    "faq.q3.answer": "Notre calculateur de calories fournit des calories, des macronutriments (protéines, glucides, lipides, sucre, fibres), la taille de portion estimée et des informations supplémentaires sur la santé des aliments identifiés.",
    "faq.q4.question": "What The Food est-il gratuit à utiliser ?",
    "faq.q4.answer": "Oui, notre scanner alimentaire IA est gratuit à utiliser et le restera toujours ! Si vous le trouvez utile et souhaitez passer vos habitudes saines au niveau supérieur, notre abonnement premium est un investissement dans votre santé qui peut rapporter.",
    "faq.q5.question": "Comment What The Food identifie-t-il les aliments à partir d'images ?",
    "faq.q5.answer": "Notre calculateur de calories alimentaires et scanner d'étiquettes nutritionnelles utilise la vision par ordinateur pour détecter et étiqueter les aliments dans votre photo, en référençant des milliers de plats et d'ingrédients connus pour donner des estimations précises de calories et de nutrition.",
    "faq.q6.question": "L'IA peut-elle vraiment estimer les calories à partir de photos d'aliments ?",
    "faq.q6.answer": "Oui ! Les scanners de calories IA comme What The Food analysent la forme, la couleur et la texture des aliments pour estimer la taille des portions et les nutriments. La précision dépend de la clarté de l'image et de la complexité des aliments.",
    "faq.q7.question": "Existe-t-il un scanner alimentaire IA gratuit en ligne ?",
    "faq.q7.answer": "Oui. What The Food propose un scanner alimentaire IA complètement gratuit. Vous pouvez télécharger des photos depuis votre appareil pour obtenir instantanément des données de calories et de nutrition, sans inscription ni carte de crédit requise.",
    "faq.q8.question": "Quelle est la précision des scanners alimentaires IA par rapport au suivi manuel des calories ?",
    "faq.q8.answer": "Les scanners alimentaires IA sont généralement précis pour les plats courants et les repas quotidiens. What The Food atteint environ 98% de précision sur les aliments standards, bien que les résultats puissent varier pour les recettes complexes ou un mauvais éclairage.",
    "faq.q9.question": "Puis-je scanner mon repas pour les calories en ligne ?",
    "faq.q9.answer": "Absolument. Vous pouvez scanner votre repas en ligne sur WhatTheFood.io — téléchargez simplement votre photo, et son analyseur alimentaire innovant décomposera chaque aliment avec des détails de calories et de macros.",
    "faq.q10.question": "What The Food suit-il mes repas ou sauvegarde-t-il mes scans ?",
    "faq.q10.answer": "Oui, en tant qu'utilisateur premium What The Food, vous aurez accès à votre historique de scans et à vos analyses de macros afin de suivre et optimiser vos habitudes saines avec un contexte de santé personnalisé.",
    "faq.q11.question": "Quels aliments l'IA peut-elle reconnaître ?",
    "faq.q11.answer": "Notre API de détection alimentaire est formée sur des milliers de plats mondiaux, de la restauration rapide aux repas faits maison, fruits, légumes et desserts. Elle peut même identifier des assiettes mixtes contenant plusieurs aliments.",
    "faq.q12.question": "Puis-je utiliser What The Food pour suivre les macros automatiquement ?",
    "faq.q12.answer": "Oui ! Notre compteur et estimateur de calories IA estime les protéines, les glucides, les lipides et les calories totales pour chaque aliment. C'est un moyen rapide d'enregistrer les repas sans taper ou peser les aliments manuellement.",
    "faq.q13.question": "Qu'est-ce qui rend What The Food différent des autres applications de scanner de calories ?",
    "faq.q13.answer": "Contrairement aux compteurs de calories traditionnels, What The Food utilise un LLM de reconnaissance alimentaire formé avec 98% de précision pour estimer les calories et les nutriments à partir de photos instantanément. Il offre également d'excellentes fonctionnalités telles qu'un planificateur de repas personnalisé, un widget personnalisable, un scanner de recettes, un calculateur de calories alimentaires, et bien plus encore, le tout avec une structure de prix très compétitive et transparente.",
    "faq.q14.question": "L'IA peut-elle estimer la taille des portions et le poids des portions à partir d'images ?",
    "faq.q14.answer": "Oui, les applications de compteur de calories de recettes comme What The Food peuvent estimer les tailles de portions en analysant la zone de l'assiette et le volume des aliments. What The Food utilise ces données pour estimer les portions et le contenu du compteur de calories plus précisément.",
    "faq.q15.question": "Existe-t-il une IA qui vous dit quel aliment se trouve dans une photo ?",
    "faq.q15.answer": "Oui ! What The Food peut vous dire exactement quel aliment se trouve dans votre photo et vous montrer sa valeur nutritionnelle. Téléchargez simplement une image et laissez l'IA faire le reste.",
    "faq.q16.question": "What The Food peut-il analyser les repas de restaurant ou les recettes ?",
    "faq.q16.answer": "Oui, vous pouvez télécharger des images de plats de restaurant ou de repas faits maison. Notre IA de calculateur de calories alimentaires identifiera chaque élément et estimera les calories, les macros et la taille des portions.",
    "faq.q17.question": "Comment fonctionnent les applications de reconnaissance alimentaire IA ?",
    "faq.q17.answer": "Ils s'appuient sur des modèles d'apprentissage profond formés sur des millions de photos d'aliments. L'IA détecte des modèles pour reconnaître les ingrédients, estimer les nutriments et renvoyer des résultats presque instantanément.",
    "faq.q18.question": "Les scanners alimentaires IA sont-ils sûrs à utiliser ?",
    "faq.q18.answer": "Oui. What The Food traite toutes les images en toute sécurité et ne nécessite pas d'informations personnelles. C'est sûr, privé et gratuit à utiliser.",
    "faq.q19.question": "Quel est le meilleur scanner alimentaire IA gratuit en 2026 ?",
    "faq.q19.answer": "What The Food est parmi les meilleurs scanners alimentaires IA gratuits en 2026, offrant une estimation rapide, précise et sans publicité des calories et des macros directement dans votre navigateur, avec trop de fonctionnalités excellentes pour optimiser vos habitudes saines.",
    "faq.security.answer": "Oui, nous prenons la confidentialité au sérieux. Vos scans alimentaires et vos données sont cryptés et jamais partagés avec des tiers. Lisez notre politique de confidentialité complète pour plus de détails.",
    
