    // Terms Page Section
    "terms.title": "Conditions Générales",
    "terms.lastupdated": "Dernière mise à jour :",
    "terms.section1.title": "1. Acceptation des Conditions",
    "terms.section1.content": "En accédant et en utilisant WhatTheFood, vous acceptez et convenez d'être lié par les termes et dispositions de cet accord.",
    "terms.section2.title": "2. Licence d'Utilisation",
    "terms.section2.content": "L'autorisation est accordée d'utiliser temporairement WhatTheFood uniquement à des fins personnelles et non commerciales. Il s'agit de l'octroi d'une licence, et non d'un transfert de titre.",
    "terms.section3.title": "3. Avertissement",
    "terms.section3.content": "Les informations nutritionnelles fournies sont à titre informatif uniquement et ne doivent pas être considérées comme des conseils médicaux. Consultez toujours un professionnel de la santé pour des conseils diététiques.",
    "terms.section4.title": "4. Conditions du Compte",
    "terms.section4.content": "Vous êtes responsable du maintien de la sécurité de votre compte et de votre mot de passe. WhatTheFood ne peut pas et ne sera pas responsable de toute perte ou dommage résultant de votre non-respect de cette obligation de sécurité.",
    "terms.section5.title": "5. Conditions d'Abonnement",
    "terms.section5.content": "Les abonnements Premium sont facturés mensuellement ou annuellement. Vous pouvez annuler votre abonnement à tout moment, et l'annulation prendra effet à la fin de votre période de facturation actuelle.",
    "terms.section6.title": "6. Modifications",
    "terms.section6.content": "WhatTheFood se réserve le droit de modifier ou de remplacer ces Conditions à tout moment. L'utilisation continue du service après tout changement constitue l'acceptation des nouvelles Conditions.",
    
    // Privacy Page Section
    "privacy.title": "Politique de Confidentialité",
    "privacy.lastupdated": "Dernière mise à jour :",
    "privacy.section1.title": "1. Informations que Nous Collectons",
    "privacy.section1.content": "Nous collectons les informations que vous nous fournissez directement, comme lorsque vous créez un compte, téléchargez des images d'aliments ou communiquez avec nous. Cela inclut votre adresse e-mail, les images téléchargées et l'historique des scans.",
    "privacy.section2.title": "2. Comment Nous Utilisons Vos Informations",
    "privacy.section2.content": "Nous utilisons les informations que nous collectons pour fournir, maintenir et améliorer nos services, y compris l'analyse d'images d'aliments et la génération de rapports nutritionnels. Nous ne vendons pas vos informations personnelles à des tiers.",
    "privacy.section3.title": "3. Sécurité des Données",
    "privacy.section3.content": "Nous mettons en œuvre des mesures techniques et organisationnelles appropriées pour protéger vos informations personnelles contre l'accès non autorisé, l'altération, la divulgation ou la destruction.",
    "privacy.section4.title": "4. Vos Droits",
