    // FAQ Section
    "faq.title": "Häufig gestellte Fragen",
    "faq.subtitle": "Alles, was Sie über unseren All-in-One-Kalorienzähler & Lebensmittelanalysator wissen müssen",
    "faq.q1.question": "Wie genau ist der What The Food Kalorienanalysator?",
    "faq.q1.answer": "Unser KI-Lebensmittel-Kalorienanalysator liefert Schätzungen mit etwa ~98% Genauigkeit für die meisten gängigen Lebensmittel. Die Ergebnisse können je nach Bildqualität und Lebensmittelkomplexität variieren.",
    "faq.q2.question": "Kann ich mehrere Lebensmittel in einem Bild analysieren?",
    "faq.q2.answer": "Ja! Der What The Food Analysator kann mehrere Lebensmittel in einem einzigen Bild identifizieren und Nährwertinformationen liefern, wie z.B. eine vollständige Mahlzeit auf einem Teller.",
    "faq.q3.question": "Welche Arten von Nährwertinformationen bietet WTFood?",
    "faq.q3.answer": "Unser Kalorienrechner liefert Kalorien, Makronährstoffe (Protein, Kohlenhydrate, Fett, Zucker, Ballaststoffe), geschätzte Portionsgröße und zusätzliche Gesundheitsinformationen über die identifizierten Lebensmittel.",
    "faq.q4.question": "Ist What The Food kostenlos zu verwenden?",
    "faq.q4.answer": "Ja, unser KI-Lebensmittelscanner ist kostenlos zu verwenden und wird es immer bleiben! Wenn Sie es nützlich finden und Ihre gesunden Gewohnheiten auf die nächste Stufe bringen möchten, ist unsere Premium-Mitgliedschaft eine Investition in Ihre Gesundheit, die sich auszahlen kann.",
    "faq.q5.question": "Wie identifiziert What The Food Lebensmittel aus Bildern?",
    "faq.q5.answer": "Unser Lebensmittel-Kalorienrechner und Nährwertkennzeichnungsscanner verwendet Computer Vision, um Lebensmittel in Ihrem Foto zu erkennen und zu kennzeichnen, wobei Tausende bekannter Gerichte und Zutaten abgeglichen werden, um genaue Kalorien- und Nährwertschätzungen zu liefern.",
    "faq.q6.question": "Kann KI wirklich Kalorien aus Lebensmittelfotos schätzen?",
    "faq.q6.answer": "Ja! KI-Kalorienscanner wie What The Food analysieren Form, Farbe und Textur von Lebensmitteln, um Portionsgröße und Nährstoffe zu schätzen. Die Genauigkeit hängt von der Bildklarheit und der Lebensmittelkomplexität ab.",
    "faq.q7.question": "Gibt es einen kostenlosen KI-Lebensmittelscanner online?",
    "faq.q7.answer": "Ja. What The Food bietet einen völlig kostenlosen KI-Lebensmittelscanner. Sie können Fotos von Ihrem Gerät hochladen, um sofort Kalorien- und Nährwertdaten zu erhalten, ohne Anmeldung oder Kreditkarte erforderlich.",
    "faq.q8.question": "Wie genau sind KI-Lebensmittelscanner im Vergleich zur manuellen Kalorienverfolgung?",
    "faq.q8.answer": "KI-Lebensmittelscanner sind im Allgemeinen genau für gängige Gerichte und alltägliche Mahlzeiten. What The Food erreicht etwa 98% Genauigkeit bei Standard-Lebensmitteln, obwohl die Ergebnisse bei komplexen Rezepten oder schlechter Beleuchtung variieren können.",
    "faq.q9.question": "Kann ich meine Mahlzeit online für Kalorien scannen?",
    "faq.q9.answer": "Absolut. Sie können Ihre Mahlzeit online auf WhatTheFood.io scannen — laden Sie einfach Ihr Foto hoch, und sein innovativer Lebensmittelanalysator wird jedes Lebensmittel mit Kalorien- und Makro-Details aufschlüsseln.",
    "faq.q10.question": "Verfolgt What The Food meine Mahlzeiten oder speichert meine Scans?",
    "faq.q10.answer": "Ja, als Premium-What The Food-Benutzer haben Sie Zugriff auf Ihren Scan-Verlauf und Makro-Analysen, damit Sie Ihre gesunden Gewohnheiten mit personalisiertem Gesundheitskontext verfolgen und optimieren können.",
    "faq.q11.question": "Welche Lebensmittel kann die KI erkennen?",
    "faq.q11.answer": "Unsere Lebensmittelerkennungs-API ist auf Tausende von globalen Gerichten trainiert, von Fast Food bis zu hausgemachten Mahlzeiten, Obst, Gemüse und Desserts. Sie kann sogar gemischte Teller mit mehreren Lebensmitteln identifizieren.",
    "faq.q12.question": "Kann ich What The Food verwenden, um Makros automatisch zu verfolgen?",
    "faq.q12.answer": "Ja! Unser KI-Kalorienzähler und -schätzer schätzt Protein, Kohlenhydrate, Fette und Gesamtkalorien für jedes Lebensmittel. Es ist eine schnelle Möglichkeit, Mahlzeiten zu protokollieren, ohne Lebensmittel manuell einzutippen oder zu wiegen.",
    "faq.q13.question": "Was macht What The Food anders als andere Kalorienscanner-Apps?",
    "faq.q13.answer": "Im Gegensatz zu traditionellen Kalorienzählern verwendet What The Food ein trainiertes Lebensmittelerkennungs-LLM mit 98% Genauigkeit, um Kalorien und Nährstoffe aus Fotos sofort zu schätzen. Es bietet auch großartige Funktionen wie personalisierten Mahlzeitenplaner, anpassbares Widget, Rezeptscanner, Lebensmittel-Kalorienrechner und vieles mehr, alles mit einer sehr wettbewerbsfähigen und transparenten Preisstruktur.",
    "faq.q14.question": "Kann KI Portionsgröße und Portionsgewicht aus Bildern schätzen?",
    "faq.q14.answer": "Ja, Kalorienzähler-Rezept-Apps wie What The Food können Portionsgrößen schätzen, indem sie Tellerfläche und Lebensmittelvolumen analysieren. What The Food verwendet diese Daten, um Portionen und Kalorienzähler-Inhalt genauer zu schätzen.",
    "faq.q15.question": "Gibt es eine KI, die Ihnen sagt, welches Lebensmittel auf einem Foto ist?",
    "faq.q15.answer": "Ja! What The Food kann Ihnen genau sagen, welches Lebensmittel auf Ihrem Foto ist und Ihnen seinen Nährwert zeigen. Laden Sie einfach ein Bild hoch und lassen Sie die KI den Rest erledigen.",
    "faq.q16.question": "Kann What The Food Restaurantmahlzeiten oder Rezepte analysieren?",
    "faq.q16.answer": "Ja, Sie können Bilder von Restaurantgerichten oder hausgemachten Mahlzeiten hochladen. Unsere KI für Lebensmittel-Kalorienschätzer wird jedes Element identifizieren und Kalorien, Makros und Portionsgröße schätzen.",
    "faq.q17.question": "Wie funktionieren KI-Lebensmittelerkennungs-Apps?",
    "faq.q17.answer": "Sie verlassen sich auf Deep-Learning-Modelle, die auf Millionen von Lebensmittelfotos trainiert wurden. Die KI erkennt Muster, um Zutaten zu erkennen, Nährstoffe zu schätzen und Ergebnisse fast sofort zurückzugeben.",
    "faq.q18.question": "Sind KI-Lebensmittelscanner sicher zu verwenden?",
    "faq.q18.answer": "Ja. What The Food verarbeitet alle Bilder sicher und erfordert keine persönlichen Informationen. Es ist sicher, privat und kostenlos zu verwenden.",
    "faq.q19.question": "Was ist der beste kostenlose KI-Lebensmittelscanner im Jahr 2026?",
    "faq.q19.answer": "What The Food gehört zu den besten kostenlosen KI-Lebensmittelscannern im Jahr 2026 und bietet schnelle, genaue und werbefreie Kalorien- und Makro-Schätzung direkt in Ihrem Browser mit zu vielen großartigen Funktionen zur Optimierung Ihrer gesunden Gewohnheiten.",
    "faq.security.answer": "Ja, wir nehmen den Datenschutz ernst. Ihre Lebensmittel-Scans und Daten sind verschlüsselt und werden niemals an Dritte weitergegeben. Lesen Sie unsere vollständige Datenschutzrichtlinie für Details.",
    
