    "terms.section3.content": "Die bereitgestellten Ernährungsinformationen dienen nur zu Informationszwecken und sollten nicht als medizinische Beratung betrachtet werden. Konsultieren Sie immer einen Gesundheitsfachmann für Ernährungsberatung.",
    "terms.section4.title": "4. Kontobedingungen",
    "terms.section4.content": "Sie sind für die Aufrechterhaltung der Sicherheit Ihres Kontos und Ihres Passworts verantwortlich. WhatTheFood kann und wird nicht für Verluste oder Schäden haftbar gemacht, die aus Ihrer Nichteinhaltung dieser Sicherheitspflicht resultieren.",
    "terms.section5.title": "5. Abonnementbedingungen",
    "terms.section5.content": "Premium-Abonnements werden monatlich oder jährlich abgerechnet. Sie können Ihr Abonnement jederzeit kündigen, und die Kündigung wird am Ende Ihres aktuellen Abrechnungszeitraums wirksam.",
    "terms.section6.title": "6. Änderungen",
    "terms.section6.content": "WhatTheFood behält sich das Recht vor, diese Bedingungen jederzeit zu ändern oder zu ersetzen. Die fortgesetzte Nutzung des Dienstes nach Änderungen stellt die Annahme der neuen Bedingungen dar.",
    
    // Privacy Page Section
    "privacy.title": "Datenschutzrichtlinie",
    "privacy.lastupdated": "Zuletzt aktualisiert:",
    "privacy.section1.title": "1. Informationen, die Wir Sammeln",
    "privacy.section1.content": "Wir sammeln Informationen, die Sie uns direkt zur Verfügung stellen, z. B. wenn Sie ein Konto erstellen, Lebensmittelbilder hochladen oder mit uns kommunizieren. Dies umfasst Ihre E-Mail-Adresse, hochgeladene Bilder und Scan-Verlauf.",
    "privacy.section2.title": "2. Wie Wir Ihre Informationen Verwenden",
    "privacy.section2.content": "Wir verwenden die von uns gesammelten Informationen, um unsere Dienste bereitzustellen, zu warten und zu verbessern, einschließlich der Analyse von Lebensmittelbildern und der Generierung von Ernährungsberichten. Wir verkaufen Ihre persönlichen Informationen nicht an Dritte.",
    "privacy.section3.title": "3. Datensicherheit",
    "privacy.section3.content": "Wir implementieren angemessene technische und organisatorische Maßnahmen, um Ihre persönlichen Informationen vor unbefugtem Zugriff, Änderung, Offenlegung oder Zerstörung zu schützen.",
    "privacy.section4.title": "4. Ihre Rechte",
    "privacy.section4.content": "Sie haben das Recht, auf Ihre persönlichen Informationen zuzugreifen, diese zu korrigieren oder zu löschen. Sie können Ihre Daten über Ihre Kontoeinstellungen oder durch direkten Kontakt mit uns verwalten.",
    "privacy.section5.title": "5. Cookies",
    "privacy.section5.content": "Wir verwenden Cookies und ähnliche Technologien, um Ihre Erfahrung zu verbessern, die Nutzung zu analysieren und unsere Marketingbemühungen zu unterstützen.",
    "privacy.section6.title": "6. Kontaktieren Sie Uns",
    "privacy.section6.content": "Wenn Sie Fragen zu dieser Datenschutzrichtlinie haben, kontaktieren Sie uns bitte unter privacy@whatthefood.io",
    
