    // FAQ Section
    "faq.title": "Domande frequenti",
    "faq.subtitle": "Tutto ciò che devi sapere sul nostro contatore di calorie e analizzatore di alimenti tutto-in-uno",
    "faq.q1.question": "Quanto è accurato l'Analizzatore di Calorie What The Food?",
    "faq.q1.answer": "Il nostro analizzatore di calorie alimentari IA fornisce stime con circa ~98% di accuratezza per la maggior parte degli alimenti comuni. I risultati possono variare in base alla qualità dell'immagine e alla complessità degli alimenti.",
    "faq.q2.question": "Posso analizzare più alimenti in un'immagine?",
    "faq.q2.answer": "Sì! L'analizzatore What The Food può identificare e fornire informazioni nutrizionali per più alimenti in una singola immagine, come un pasto completo su un piatto.",
    "faq.q3.question": "Che tipi di informazioni nutrizionali fornisce WTFood?",
    "faq.q3.answer": "Il nostro calcolatore di calorie fornisce calorie, macronutrienti (proteine, carboidrati, grassi, zucchero, fibre), dimensione della porzione stimata e informazioni aggiuntive sulla salute degli alimenti identificati.",
    "faq.q4.question": "What The Food è gratuito da usare?",
    "faq.q4.answer": "Sì, il nostro scanner alimentare IA è gratuito da usare e lo rimarrà sempre! Se lo trovi utile e vuoi portare le tue abitudini sane al livello successivo, la nostra membership premium è un investimento nella tua salute che può dare dividendi.",
    "faq.q5.question": "Come identifica What The Food gli alimenti dalle immagini?",
    "faq.q5.answer": "Il nostro calcolatore di calorie alimentari e scanner di etichette nutrizionali utilizza la visione artificiale per rilevare ed etichettare gli alimenti nella tua foto, incrociando migliaia di piatti e ingredienti noti per dare stime accurate di calorie e nutrizione.",
    "faq.q6.question": "L'IA può davvero stimare le calorie dalle foto di cibo?",
    "faq.q6.answer": "Sì! Gli scanner di calorie IA come What The Food analizzano forma, colore e consistenza del cibo per stimare la dimensione della porzione e i nutrienti. L'accuratezza dipende dalla chiarezza dell'immagine e dalla complessità del cibo.",
    "faq.q7.question": "C'è uno scanner alimentare IA gratuito online?",
    "faq.q7.answer": "Sì. What The Food offre uno scanner alimentare IA completamente gratuito. Puoi caricare foto dal tuo dispositivo per ottenere istantaneamente dati di calorie e nutrizione, senza registrazioni o carte di credito richieste.",
    "faq.q8.question": "Quanto sono accurati gli scanner alimentari IA rispetto al tracciamento manuale delle calorie?",
    "faq.q8.answer": "Gli scanner alimentari IA sono generalmente accurati per piatti comuni e pasti quotidiani. What The Food raggiunge circa il 98% di accuratezza su alimenti standard, sebbene i risultati possano variare per ricette complesse o scarsa illuminazione.",
    "faq.q9.question": "Posso scansionare il mio pasto per le calorie online?",
    "faq.q9.answer": "Assolutamente. Puoi scansionare il tuo pasto online su WhatTheFood.io — carica semplicemente la tua foto, e il suo innovativo analizzatore alimentare scomporrà ogni alimento con dettagli di calorie e macro.",
    "faq.q10.question": "What The Food traccia i miei pasti o salva le mie scansioni?",
    "faq.q10.answer": "Sì, come utente premium What The Food avrai accesso alla tua cronologia di scansioni e analisi macro così puoi tenere traccia e ottimizzare le tue abitudini sane con contesto sanitario personalizzato.",
    "faq.q11.question": "Quali alimenti può riconoscere l'IA?",
    "faq.q11.answer": "La nostra API di rilevamento alimentare è addestrata su migliaia di piatti globali, dal fast food ai pasti fatti in casa, frutta, verdura e dessert. Può persino identificare piatti misti contenenti più alimenti.",
    "faq.q12.question": "Posso usare What The Food per tracciare i macro automaticamente?",
    "faq.q12.answer": "Sì! Il nostro contatore e stimatore di calorie IA stima proteine, carboidrati, grassi e calorie totali per ogni alimento. È un modo veloce per registrare i pasti senza digitare o pesare il cibo manualmente.",
    "faq.q13.question": "Cosa rende What The Food diverso da altre app scanner di calorie?",
    "faq.q13.answer": "A differenza dei contatori di calorie tradizionali, What The Food utilizza un LLM di riconoscimento alimentare addestrato con 98% di accuratezza per stimare calorie e nutrienti dalle foto istantaneamente. Offre anche fantastiche funzionalità come pianificatore di pasti personalizzato, widget personalizzabile, scanner di ricette, calcolatore di calorie alimentari e molto altro, tutto con una struttura di prezzi molto competitiva e trasparente.",
    "faq.q14.question": "L'IA può stimare la dimensione della porzione e il peso della porzione dalle immagini?",
    "faq.q14.answer": "Sì, le app contatore di calorie per ricette come What The Food possono stimare le dimensioni delle porzioni analizzando l'area del piatto e il volume del cibo. What The Food usa questi dati per stimare porzioni e contenuto del contatore di calorie più accuratamente.",
    "faq.q15.question": "C'è un'IA che ti dice quale cibo c'è in una foto?",
    "faq.q15.answer": "Sì! What The Food può dirti esattamente quale cibo c'è nella tua foto e mostrarti il suo valore nutrizionale. Carica semplicemente un'immagine e lascia che l'IA faccia il resto.",
    "faq.q16.question": "What The Food può analizzare pasti da ristorante o ricette?",
    "faq.q16.answer": "Sì, puoi caricare immagini di piatti da ristorante o pasti fatti in casa. La nostra IA stimatore di calorie alimentari identificherà ogni elemento e stimerà calorie, macro e dimensione della porzione.",
    "faq.q17.question": "Come funzionano le app di riconoscimento alimentare IA?",
    "faq.q17.answer": "Si basano su modelli di deep learning addestrati su milioni di foto di cibo. L'IA rileva pattern per riconoscere ingredienti, stimare nutrienti e restituire risultati quasi istantaneamente.",
    "faq.q18.question": "Gli scanner alimentari IA sono sicuri da usare?",
    "faq.q18.answer": "Sì. What The Food elabora tutte le immagini in modo sicuro e non richiede informazioni personali. È sicuro, privato e gratuito da usare.",
    "faq.q19.question": "Qual è il migliore scanner alimentare IA gratuito nel 2026?",
    "faq.q19.answer": "What The Food è tra i migliori scanner alimentari IA gratuiti nel 2026, offrendo stima rapida, accurata e senza pubblicità di calorie e macro direttamente nel tuo browser, con troppe fantastiche funzionalità per ottimizzare le tue abitudini sane.",
    
