    // FAQ Section
    "faq.title": "Perguntas frequentes",
    "faq.subtitle": "Tudo que você precisa saber sobre nosso contador de calorias e analisador de alimentos tudo-em-um",
    "faq.q1.question": "Quão preciso é o Analisador de Calorias What The Food?",
    "faq.q1.answer": "Nosso analisador de calorias de alimentos IA fornece estimativas com aproximadamente ~98% de precisão para a maioria dos alimentos comuns. Os resultados podem variar com base na qualidade da imagem e complexidade dos alimentos.",
    "faq.q2.question": "Posso analisar vários alimentos em uma imagem?",
    "faq.q2.answer": "Sim! O analisador What The Food pode identificar e fornecer informações nutricionais para vários alimentos em uma única imagem, como uma refeição completa em um prato.",
    "faq.q3.question": "Que tipos de informações nutricionais o WTFood fornece?",
    "faq.q3.answer": "Nosso calculador de calorias fornece calorias, macronutrientes (proteína, carboidratos, gordura, açúcar, fibra), tamanho de porção estimado e informações adicionais sobre a saúde dos alimentos identificados.",
    "faq.q4.question": "O What The Food é gratuito para usar?",
    "faq.q4.answer": "Sim, nosso scanner de alimentos IA é gratuito para usar e sempre permanecerá assim! Se você está achando útil e quer levar seus hábitos saudáveis para o próximo nível, nossa assinatura premium é um investimento em sua saúde que pode dar retornos.",
    "faq.q5.question": "Como o What The Food identifica alimentos de imagens?",
    "faq.q5.answer": "Nosso calculador de calorias de alimentos e scanner de rótulos nutricionais usa visão computacional para detectar e rotular alimentos em sua foto, cruzando referências de milhares de pratos e ingredientes conhecidos para dar estimativas precisas de calorias e nutrição.",
    "faq.q6.question": "A IA pode realmente estimar calorias de fotos de alimentos?",
    "faq.q6.answer": "Sim! Os scanners de calorias IA como What The Food analisam a forma, cor e textura dos alimentos para estimar o tamanho da porção e os nutrientes. A precisão depende da clareza da imagem e da complexidade dos alimentos.",
    "faq.q7.question": "Existe um scanner de alimentos IA gratuito online?",
    "faq.q7.answer": "Sim. O What The Food oferece um scanner de alimentos IA completamente gratuito. Você pode fazer upload de fotos do seu dispositivo para obter instantaneamente dados de calorias e nutrição, sem cadastros ou cartões de crédito necessários.",
    "faq.q8.question": "Quão precisos são os scanners de alimentos IA comparados ao rastreamento manual de calorias?",
    "faq.q8.answer": "Os scanners de alimentos IA são geralmente precisos para pratos comuns e refeições cotidianas. O What The Food alcança cerca de 98% de precisão em alimentos padrão, embora os resultados possam variar para receitas complexas ou iluminação ruim.",
    "faq.q9.question": "Posso escanear minha refeição para calorias online?",
    "faq.q9.answer": "Absolutamente. Você pode escanear sua refeição online em WhatTheFood.io — simplesmente faça upload da sua foto, e seu analisador de alimentos inovador quebrará cada alimento com detalhes de calorias e macros.",
    "faq.q10.question": "O What The Food rastreia minhas refeições ou salva meus escaneamentos?",
    "faq.q10.answer": "Sim, como usuário premium do What The Food, você terá acesso ao seu histórico de escaneamentos e análises de macros para que possa acompanhar e otimizar seus hábitos saudáveis com contexto de saúde personalizado.",
    "faq.q11.question": "Quais alimentos a IA pode reconhecer?",
    "faq.q11.answer": "Nossa API de detecção de alimentos é treinada em milhares de pratos globais, de fast food a refeições caseiras, frutas, vegetais e sobremesas. Ela pode até identificar pratos mistos contendo vários alimentos.",
    "faq.q12.question": "Posso usar o What The Food para rastrear macros automaticamente?",
    "faq.q12.answer": "Sim! Nosso contador e estimador de calorias IA estima proteínas, carboidratos, gorduras e calorias totais para cada alimento. É uma maneira rápida de registrar refeições sem digitar ou pesar alimentos manualmente.",
    "faq.q13.question": "O que torna o What The Food diferente de outros aplicativos de scanner de calorias?",
    "faq.q13.answer": "Ao contrário dos contadores de calorias tradicionais, o What The Food usa um LLM de reconhecimento de alimentos treinado com 98% de precisão para estimar calorias e nutrientes de fotos instantaneamente. Também oferece ótimas funcionalidades como planejador de refeições personalizado, widget personalizável, scanner de receitas, calculador de calorias de alimentos e muito mais, tudo com uma estrutura de preços muito competitiva e transparente.",
    "faq.q14.question": "A IA pode estimar o tamanho da porção e o peso da porção de imagens?",
    "faq.q14.answer": "Sim, aplicativos de contador de calorias de receitas como What The Food podem estimar tamanhos de porção analisando a área do prato e o volume dos alimentos. O What The Food usa esses dados para estimar porções e conteúdo do contador de calorias com mais precisão.",
    "faq.q15.question": "Existe uma IA que te diz qual alimento está em uma foto?",
    "faq.q15.answer": "Sim! O What The Food pode te dizer exatamente qual alimento está na sua foto e mostrar seu valor nutricional. Basta fazer upload de uma imagem e deixar a IA fazer o resto.",
    "faq.q16.question": "O What The Food pode analisar refeições de restaurante ou receitas?",
    "faq.q16.answer": "Sim, você pode fazer upload de imagens de pratos de restaurante ou refeições caseiras. Nossa IA estimadora de calorias de alimentos identificará cada item e estimará calorias, macros e tamanho da porção.",
    "faq.q17.question": "Como funcionam os aplicativos de reconhecimento de alimentos IA?",
    "faq.q17.answer": "Eles dependem de modelos de aprendizado profundo treinados em milhões de fotos de alimentos. A IA detecta padrões para reconhecer ingredientes, estimar nutrientes e retornar resultados quase instantaneamente.",
    "faq.q18.question": "Os scanners de alimentos IA são seguros para usar?",
    "faq.q18.answer": "Sim. O What The Food processa todas as imagens com segurança e não requer informações pessoais. É seguro, privado e gratuito para usar.",
    "faq.q19.question": "Qual é o melhor scanner de alimentos IA gratuito em 2026?",
    "faq.q19.answer": "O What The Food está entre os melhores scanners de alimentos IA gratuitos em 2026, oferecendo estimativa rápida, precisa e sem anúncios de calorias e macros diretamente no seu navegador, com muitas funcionalidades excelentes para otimizar seus hábitos saudáveis.",
    
