    // Terms Page Section
    "terms.title": "Termos e Condições",
    "terms.lastupdated": "Última atualização:",
    "terms.section1.title": "1. Aceitação dos Termos",
    "terms.section1.content": "Ao acessar e usar o WhatTheFood, você aceita e concorda em estar vinculado aos termos e disposições deste acordo.",
    "terms.section2.title": "2. Licença de Uso",
    "terms.section2.content": "É concedida permissão para usar temporariamente o WhatTheFood apenas para uso pessoal e não comercial. Esta é a concessão de uma licença, não uma transferência de título.",
    "terms.section3.title": "3. Aviso Legal",
    "terms.section3.content": "As informações nutricionais fornecidas são apenas para fins informativos e não devem ser consideradas aconselhamento médico. Sempre consulte um profissional de saúde para orientação dietética.",
    "terms.section4.title": "4. Termos da Conta",
    "terms.section4.content": "Você é responsável por manter a segurança da sua conta e senha. O WhatTheFood não pode e não será responsável por qualquer perda ou dano decorrente do seu não cumprimento desta obrigação de segurança.",
    "terms.section5.title": "5. Termos de Assinatura",
    "terms.section5.content": "As assinaturas Premium são cobradas mensal ou anualmente. Você pode cancelar sua assinatura a qualquer momento, e o cancelamento entrará em vigor no final do seu período de faturamento atual.",
    "terms.section6.title": "6. Modificações",
    "terms.section6.content": "O WhatTheFood se reserva o direito de modificar ou substituir estes Termos a qualquer momento. O uso contínuo do serviço após quaisquer alterações constitui a aceitação dos novos Termos.",
    
    // Privacy Page Section
    "privacy.title": "Política de Privacidade",
    "privacy.lastupdated": "Última atualização:",
    "privacy.section1.title": "1. Informações que Coletamos",
    "privacy.section1.content": "Coletamos informações que você nos fornece diretamente, como quando você cria uma conta, faz upload de imagens de alimentos ou se comunica conosco. Isso inclui seu endereço de e-mail, imagens enviadas e histórico de escaneamentos.",
    "privacy.section2.title": "2. Como Usamos Suas Informações",
    "privacy.section2.content": "Usamos as informações que coletamos para fornecer, manter e melhorar nossos serviços, incluindo análise de imagens de alimentos e geração de relatórios nutricionais. Não vendemos suas informações pessoais a terceiros.",
    "privacy.section3.title": "3. Segurança de Dados",
    "privacy.section3.content": "Implementamos medidas técnicas e organizacionais apropriadas para proteger suas informações pessoais contra acesso não autorizado, alteração, divulgação ou destruição.",
    "privacy.section4.title": "4. Seus Direitos",
    "privacy.section4.content": "Você tem o direito de acessar, corrigir ou excluir suas informações pessoais. Você pode gerenciar seus dados através das configurações da sua conta ou entrando em contato conosco diretamente.",
    "privacy.section5.title": "5. Cookies",
    "privacy.section5.content": "Usamos cookies e tecnologias similares para melhorar sua experiência, analisar o uso e auxiliar em nossos esforços de marketing.",
    "privacy.section6.title": "6. Entre em Contato",
    "privacy.section6.content": "Se você tiver dúvidas sobre esta Política de Privacidade, entre em contato conosco em privacy@whatthefood.io",
    
