    // FAQ Section
    "faq.title": "常见问题",
    "faq.subtitle": "关于我们一体化卡路里计数器和食物分析器您需要了解的一切",
    "faq.q1.question": "What The Food卡路里分析器的准确性如何？",
    "faq.q1.answer": "我们的AI食物卡路里分析器对大多数常见食物提供约~98%准确度的估算。结果可能因图像质量和食物复杂性而异。",
    "faq.q2.question": "我可以在一张图片中分析多种食物吗？",
    "faq.q2.answer": "可以！What The Food分析器可以识别并提供一张图片中多种食物的营养信息，例如盘子中的完整一餐。",
    "faq.q3.question": "WTFood提供哪些类型的营养信息？",
    "faq.q3.answer": "我们的卡路里计算器提供卡路里、宏量营养素（蛋白质、碳水化合物、脂肪、糖、纤维）、估计份量以及关于已识别食物的额外健康洞察。",
    "faq.q4.question": "What The Food是免费使用的吗？",
    "faq.q4.answer": "是的，我们的AI食物扫描器是免费使用的，并将始终保持免费！如果您觉得它有用并想将健康习惯提升到新水平，我们的高级会员是对您健康的投资，可以带来回报。",
    "faq.q5.question": "What The Food如何从图像中识别食物？",
    "faq.q5.answer": "我们的食物卡路里计算器和营养标签扫描器使用计算机视觉来检测和标记您照片中的食物，交叉参考数千种已知菜肴和成分，以提供准确的卡路里和营养估算。",
    "faq.q6.question": "AI真的能从食物照片中估算卡路里吗？",
    "faq.q6.answer": "是的！像What The Food这样的AI卡路里扫描器分析食物的形状、颜色和质地来估算份量和营养素。准确性取决于图像清晰度和食物复杂性。",
    "faq.q7.question": "有免费的在线AI食物扫描器吗？",
    "faq.q7.answer": "是的。What The Food提供完全免费的AI食物扫描器。您可以从设备上传照片，立即获得卡路里和营养数据，无需注册或信用卡。",
    "faq.q8.question": "AI食物扫描器与手动卡路里追踪相比有多准确？",
    "faq.q8.answer": "AI食物扫描器对于常见菜肴和日常餐食通常是准确的。What The Food在标准食物上达到约98%的准确性，尽管对于复杂食谱或光线不佳的情况，结果可能会有所不同。",
    "faq.q9.question": "我可以在线扫描我的餐食以获取卡路里吗？",
    "faq.q9.answer": "当然可以。您可以在WhatTheFood.io在线扫描您的餐食——只需上传您的照片，其创新的食物分析器将分解每种食物，提供卡路里和宏量营养素详情。",
    "faq.q10.question": "What The Food会追踪我的餐食或保存我的扫描吗？",
    "faq.q10.answer": "是的，作为What The Food高级用户，您将可以访问您的扫描历史和宏量营养素分析，以便您可以跟踪和优化您的健康习惯，并获得个性化的健康背景。",
    "faq.q11.question": "AI可以识别哪些食物？",
    "faq.q11.answer": "我们的食物检测API在数千种全球菜肴上训练，从快餐到家常菜、水果、蔬菜和甜点。它甚至可以识别包含多种食物的混合盘子。",
    "faq.q12.question": "我可以使用What The Food自动追踪宏量营养素吗？",
    "faq.q12.answer": "可以！我们的AI卡路里计数器和估算器估算每种食物的蛋白质、碳水化合物、脂肪和总卡路里。这是记录餐食的快速方法，无需手动输入或称重食物。",
    "faq.q13.question": "What The Food与其他卡路里扫描应用有什么不同？",
    "faq.q13.answer": "与传统的卡路里计数器不同，What The Food使用训练有素的食物识别LLM，准确率达98%，可以立即从照片中估算卡路里和营养素。它还提供出色的功能，如个性化膳食计划器、可自定义小部件、食谱扫描器、食物卡路里计算器等，所有这些都具有非常具有竞争力和透明的定价结构。",
    "faq.q14.question": "AI可以从图片中估算份量和份量重量吗？",
    "faq.q14.answer": "可以，像What The Food这样的卡路里计数器食谱应用可以通过分析盘子面积和食物体积来估算份量。What The Food使用这些数据更准确地估算份量和卡路里计数器内容。",
    "faq.q15.question": "有AI可以告诉您照片中有什么食物吗？",
    "faq.q15.answer": "有！What The Food可以准确告诉您照片中有什么食物，并向您展示其营养价值。只需上传一张图片，让AI完成其余工作。",
    "faq.q16.question": "What The Food可以分析餐厅餐食或食谱吗？",
    "faq.q16.answer": "可以，您可以上传餐厅菜肴或家常菜的照片。我们的食物卡路里估算器AI将识别每个项目并估算卡路里、宏量营养素和份量。",
    "faq.q17.question": "AI食物识别应用如何工作？",
    "faq.q17.answer": "它们依赖于在数百万食物照片上训练的深度学习模型。AI检测模式以识别成分、估算营养素，并几乎立即返回结果。",
    "faq.q18.question": "AI食物扫描器使用安全吗？",
    "faq.q18.answer": "安全。What The Food安全处理所有图像，不需要个人信息。它安全、私密且免费使用。",
    "faq.q19.question": "2026年最好的免费AI食物扫描器是什么？",
    "faq.q19.answer": "What The Food是2026年最好的免费AI食物扫描器之一，直接在您的浏览器中提供快速、准确且无广告的卡路里和宏量营养素估算，具有太多出色的功能来优化您的健康习惯。",
    
