    // Terms Page Section
    "terms.title": "条款和条件",
    "terms.lastupdated": "最后更新：",
    "terms.section1.title": "1. 接受条款",
    "terms.section1.content": "通过访问和使用WhatTheFood，您接受并同意受本协议的条款和规定约束。",
    "terms.section2.title": "2. 使用许可",
    "terms.section2.content": "仅允许临时使用WhatTheFood用于个人、非商业用途。这是授予许可，而非所有权转让。",
    "terms.section3.title": "3. 免责声明",
    "terms.section3.content": "提供的营养信息仅供参考，不应被视为医疗建议。请始终咨询医疗专业人士以获得饮食指导。",
    "terms.section4.title": "4. 账户条款",
    "terms.section4.content": "您有责任维护账户和密码的安全。WhatTheFood不对您未能遵守此安全义务而造成的任何损失或损害承担责任。",
    "terms.section5.title": "5. 订阅条款",
    "terms.section5.content": "Premium订阅按月或按年计费。您可以随时取消订阅，取消将在当前计费周期结束时生效。",
    "terms.section6.title": "6. 修改",
    "terms.section6.content": "WhatTheFood保留随时修改或替换这些条款的权利。任何更改后继续使用服务即表示接受新条款。",
    
    // Privacy Page Section
    "privacy.title": "隐私政策",
    "privacy.lastupdated": "最后更新：",
    "privacy.section1.title": "1. 我们收集的信息",
    "privacy.section1.content": "我们收集您直接提供给我们的信息，例如当您创建账户、上传食物图像或与我们沟通时。这包括您的电子邮件地址、上传的图像和扫描历史。",
    "privacy.section2.title": "2. 我们如何使用您的信息",
    "privacy.section2.content": "我们使用收集的信息来提供、维护和改进我们的服务，包括分析食物图像和生成营养报告。我们不会将您的个人信息出售给第三方。",
    "privacy.section3.title": "3. 数据安全",
    "privacy.section3.content": "我们实施适当的技术和组织措施，以保护您的个人信息免受未经授权的访问、更改、披露或破坏。",
    "privacy.section4.title": "4. 您的权利",
    "privacy.section4.content": "您有权访问、更正或删除您的个人信息。您可以通过账户设置或直接联系我们来管理您的数据。",
    "privacy.section5.title": "5. Cookie",
    "privacy.section5.content": "我们使用cookie和类似技术来增强您的体验、分析使用情况并协助我们的营销工作。",
    "privacy.section6.title": "6. 联系我们",
    "privacy.section6.content": "如果您对此隐私政策有疑问，请通过privacy@whatthefood.io联系我们",
    
