    // FAQ Section
    "faq.title": "よくある質問",
    "faq.subtitle": "当社のオールインワンカロリーカウンター＆食品分析器について知っておくべきすべて",
    "faq.q1.question": "What The Foodカロリー分析器の精度はどのくらいですか？",
    "faq.q1.answer": "当社のAI食品カロリー分析器は、ほとんどの一般的な食品に対して約~98%の精度で推定値を提供します。結果は画像の品質と食品の複雑さによって異なる場合があります。",
    "faq.q2.question": "1つの画像で複数の食品を分析できますか？",
    "faq.q2.answer": "はい！What The Food分析器は、1つの画像内の複数の食品を識別し、栄養情報を提供できます。たとえば、プレート上の完全な食事などです。",
    "faq.q3.question": "WTFoodはどのような種類の栄養情報を提供しますか？",
    "faq.q3.answer": "当社のカロリー計算機は、カロリー、マクロ栄養素（タンパク質、炭水化物、脂肪、糖、繊維）、推定サービングサイズ、および識別された食品に関する追加の健康情報を提供します。",
    "faq.q4.question": "What The Foodは無料で使用できますか？",
    "faq.q4.answer": "はい、当社のAI食品スキャナーは無料で使用でき、常に無料のままです！便利だと感じ、健康的な習慣を次のレベルに引き上げたい場合は、プレミアムメンバーシップは健康への投資であり、見返りを得ることができます。",
    "faq.q5.question": "What The Foodは画像から食品をどのように識別しますか？",
    "faq.q5.answer": "当社の食品カロリー計算機と栄養ラベルスキャナーは、コンピュータビジョンを使用して写真内の食品を検出し、ラベル付けし、数千の既知の料理と材料を相互参照して、正確なカロリーと栄養の推定値を提供します。",
    "faq.q6.question": "AIは本当に食品写真からカロリーを推定できますか？",
    "faq.q6.answer": "はい！What The FoodのようなAIカロリースキャナーは、食品の形状、色、質感を分析して、サービングサイズと栄養素を推定します。精度は画像の明瞭さと食品の複雑さに依存します。",
    "faq.q7.question": "無料のオンラインAI食品スキャナーはありますか？",
    "faq.q7.answer": "はい。What The Foodは完全に無料のAI食品スキャナーを提供しています。デバイスから写真をアップロードして、即座にカロリーと栄養データを取得できます。登録やクレジットカードは不要です。",
    "faq.q8.question": "AI食品スキャナーは手動のカロリートラッキングと比較してどのくらい正確ですか？",
    "faq.q8.answer": "AI食品スキャナーは、一般的な料理や日常の食事に対して一般的に正確です。What The Foodは標準的な食品で約98%の精度を達成しますが、複雑なレシピや照明が悪い場合、結果は異なる場合があります。",
    "faq.q9.question": "オンラインで食事をスキャンしてカロリーを取得できますか？",
    "faq.q9.answer": "もちろんです。WhatTheFood.ioでオンラインで食事をスキャンできます—写真をアップロードするだけで、革新的な食品分析器が各食品をカロリーとマクロの詳細で分解します。",
    "faq.q10.question": "What The Foodは私の食事を追跡したり、スキャンを保存したりしますか？",
    "faq.q10.answer": "はい、What The Foodプレミアムユーザーとして、スキャン履歴とマクロ分析にアクセスできるため、パーソナライズされた健康コンテキストで健康的な習慣を追跡し、最適化できます。",
    "faq.q11.question": "AIはどのような食品を認識できますか？",
    "faq.q11.answer": "当社の食品検出APIは、ファストフードから家庭料理、果物、野菜、デザートまで、数千のグローバルな料理で訓練されています。複数の食品を含む混合プレートも識別できます。",
    "faq.q12.question": "What The Foodを使用してマクロを自動的に追跡できますか？",
    "faq.q12.answer": "はい！当社のAIカロリーカウンターと推定器は、各食品のタンパク質、炭水化物、脂肪、総カロリーを推定します。手動で入力したり、食品を計量したりせずに食事を記録する迅速な方法です。",
    "faq.q13.question": "What The Foodを他のカロリースキャナーアプリと異なるものにするのは何ですか？",
    "faq.q13.answer": "従来のカロリーカウンターとは異なり、What The Foodは98%の精度で訓練された食品認識LLMを使用して、写真からカロリーと栄養素を即座に推定します。また、パーソナライズされた食事プランナー、カスタマイズ可能なウィジェット、レシピスキャナー、食品カロリー計算機など、多くの優れた機能を提供し、すべて非常に競争力があり透明な価格構造を備えています。",
    "faq.q14.question": "AIは画像からサービングサイズとサービング重量を推定できますか？",
    "faq.q14.answer": "はい、What The Foodのようなカロリーカウンターレシピアプリは、プレートエリアと食品の体積を分析してサービングサイズを推定できます。What The Foodはこのデータを使用して、サービングとカロリーカウンターの内容をより正確に推定します。",
    "faq.q15.question": "写真にどの食品があるかを教えてくれるAIはありますか？",
    "faq.q15.answer": "はい！What The Foodは、写真に正確にどの食品があるかを教え、その栄養価を示すことができます。画像をアップロードするだけで、AIが残りを行います。",
    "faq.q16.question": "What The Foodはレストランの食事やレシピを分析できますか？",
    "faq.q16.answer": "はい、レストランの料理や家庭料理の画像をアップロードできます。当社の食品カロリー推定器AIは、各アイテムを識別し、カロリー、マクロ、サービングサイズを推定します。",
    "faq.q17.question": "AI食品認識アプリはどのように機能しますか？",
    "faq.q17.answer": "それらは、数百万の食品写真で訓練された深層学習モデルに依存しています。AIはパターンを検出して、材料を認識し、栄養素を推定し、ほぼ即座に結果を返します。",
    "faq.q18.question": "AI食品スキャナーは安全に使用できますか？",
    "faq.q18.answer": "はい。What The Foodはすべての画像を安全に処理し、個人情報を必要としません。安全でプライベート、無料で使用できます。",
    "faq.q19.question": "2026年の最高の無料AI食品スキャナーは何ですか？",
    "faq.q19.answer": "What The Foodは、2026年の最高の無料AI食品スキャナーの1つで、ブラウザで直接、迅速で正確、広告なしのカロリーとマクロの推定を提供し、健康的な習慣を最適化するための優れた機能が多数あります。",
    
